settings":{"html":"
<style>
  :root {
    --primary: #1a3c6e;
    --accent: #f7941d;
    --light-bg: #f0f4fb;
    --card-bg: #ffffff;
    --text-main: #1a2940;
    --text-sub: #4a6080;
    --border: #dde6f5;
    --tag-bg: #e8f0fd;
    --tag-text: #1a3c6e;
    --success: #1e9e6b;
  }

  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Nunito', sans-serif;
    background: var(--light-bg);
    color: var(--text-main);

  }

  .section-header {
    text-align: center;
    margin-bottom: 28px;
  }

  .section-header .badge {
    display: inline-block;
    background: var(--accent);
    color: #fff;
    font-family: 'Poppins', sans-serif;
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 2px;
    text-transform: uppercase;
    padding: 5px 16px;
    border-radius: 20px;
    margin-bottom: 12px;
  }

  .section-header h2 {
    font-family: 'Poppins', sans-serif;
    font-size: 26px;
    font-weight: 700;
    color: var(--primary);
    line-height: 1.3;
  }

  .section-header h2 span { color: var(--accent); }

  .section-header p {
    margin-top: 10px;
    color: var(--text-sub);
    font-size: 14px;
  }

  .count-bar {
    text-align: center;
    margin: 0 auto 32px;
    padding: 16px 24px;
    background: linear-gradient(135deg, var(--primary), #2a5aaa);
    border-radius: 14px;
    max-width: 500px;
    color: #fff;
  }

  .count-bar .count-num {
    font-family: 'Poppins', sans-serif;
    font-size: 46px;
    font-weight: 800;
    line-height: 1;
    color: var(--accent);
  }

  .count-bar .count-label {
    font-size: 13px;
    opacity: 0.85;
    margin-top: 4px;
  }

  /* State section headings */
  .state-section {
    max-width: 1100px;
    margin: 0 auto 10px;
    padding: 0 16px;
  }

  .state-heading {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 14px;
    margin-top: 28px;
  }

  .state-heading .state-label {
    font-family: 'Poppins', sans-serif;
    font-size: 13px;
    font-weight: 700;
    color: var(--primary);
    background: var(--tag-bg);
    padding: 4px 14px;
    border-radius: 20px;
    border: 1.5px solid var(--border);
    white-space: nowrap;
  }

  .state-heading .line {
    flex: 1;
    height: 1.5px;
    background: var(--border);
    border-radius: 2px;
  }

  /* Grid */
  .schools-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(255px, 1fr));
    gap: 16px;
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 16px;
  }

  /* Card */
  .school-card {
    background: var(--card-bg);
    border: 1.5px solid var(--border);
    border-radius: 14px;
    padding: 20px 18px 16px;
    display: flex;
    flex-direction: column;
    gap: 9px;
    box-shadow: 0 2px 10px rgba(26,60,110,0.06);
    transition: transform 0.2s, box-shadow 0.2s, border-color 0.2s;
    position: relative;
    overflow: hidden;
  }

  .school-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 4px;
    height: 100%;
    background: linear-gradient(180deg, var(--accent), var(--primary));
    border-radius: 14px 0 0 14px;
  }

  .school-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 8px 26px rgba(26,60,110,0.13);
    border-color: var(--accent);
  }

  .school-icon {
    width: 42px;
    height: 42px;
    border-radius: 11px;
    background: var(--tag-bg);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  .school-icon svg {
    width: 22px;
    height: 22px;
    fill: none;
    stroke: var(--primary);
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .school-name {
    font-family: 'Poppins', sans-serif;
    font-size: 13.5px;
    font-weight: 700;
    color: var(--primary);
    line-height: 1.35;
  }

  .school-location {
    display: flex;
    align-items: center;
    gap: 5px;
    color: var(--text-sub);
    font-size: 12px;
    font-weight: 600;
  }

  .school-location svg {
    width: 12px;
    height: 12px;
    flex-shrink: 0;
    stroke: var(--accent);
    fill: none;
    stroke-width: 2.2;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  .installed-badge {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    background: #e6f7f1;
    color: var(--success);
    font-size: 10.5px;
    font-weight: 700;
    padding: 3px 9px;
    border-radius: 20px;
    width: fit-content;
  }

  .installed-badge svg {
    width: 11px;
    height: 11px;
    stroke: var(--success);
    fill: none;
    stroke-width: 2.5;
    stroke-linecap: round;
    stroke-linejoin: round;
  }

  @media (max-width: 600px) {
    .schools-grid { grid-template-columns: 1fr; }
    .section-header h2 { font-size: 20px; }
     .section-header p { padding-left: 20px;padding-right: 20px; }
    .count-bar{max-width: 380px;}
  }
</style>


<div class="section-header">
  <div class="badge"> EduMEasy Math Lab</div>
  <h2>Schools Using Our <span>Math Lab</span></h2>
  <p>EduMEasy Math Lab successfully installed &amp; running across India</p>
</div>

<div class="count-bar">
  <div class="count-num">500+</div>
  <div class="count-label">Schools Across India</div>
</div>

